import type { GeospatialCamera } from "@babylonjs/lite";

export function tiltGlobeCamera(camera: GeospatialCamera, pitch: number): void {
  const yaw = camera.yaw;
  const radius = camera.radius;
  const center = camera.center;
  const desiredPitch = pitch;

  const limits = camera.limits;
  if (limits) {
    limits.pitchMin = Math.min(limits.pitchMin ?? 0, desiredPitch);
    limits.pitchMax = Math.max(limits.pitchMax ?? Math.PI / 2, desiredPitch);
    // Disable radius-based pitch locking so it works at full zoom and remains after zoom changes.
    limits.pitchDisabledRadiusScale = null;
  }

  // Use exact internal setter if available to avoid public clamping.
  camera._setOrientation(yaw, desiredPitch, radius, center);

  // Ensure lookAt computed at exact pitch, in case the internal setter only stores pitch but not view target.
  // computeLookAtFromYawPitch writes into result. _lookAt is mutable.
  computeLookAtFromYawPitch(yaw, desiredPitch, center, camera._lookAt);
}

