import type { GeospatialCamera } from "@babylonjs/lite";

export function tiltGlobeCamera(camera: GeospatialCamera, pitch: number): void {
  if (!Number.isFinite(pitch)) {
    return;
  }

  const yaw = camera.yaw;
  const radius = camera.radius;
  const center = camera.center;

  const limits = camera.limits;
  if (limits) {
    if (Number.isFinite(limits.pitchMin)) {
      limits.pitchMin = Math.min(limits.pitchMin, pitch);
    } else {
      limits.pitchMin = pitch;
    }

    if (Number.isFinite(limits.pitchMax)) {
      limits.pitchMax = Math.max(limits.pitchMax, pitch);
    } else {
      limits.pitchMax = pitch;
    }

    // Remove radius-based pitch clamping so the tilt survives zoom changes.
    limits.pitchDisabledRadiusScale = null;
  }

  // Use the exact orientation setter to keep yaw/radius/center and force pitch.
  camera._setOrientation(yaw, pitch, radius, center);
}
```
